package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/yaseir-agent/agent/internal/config"
)

// Only the evidence generated by CaptureTestDocument is eligible. In
// particular, neither configs, secrets, queue data, arbitrary PDFs nor a
// still-running (fresh) capture may be removed by this command.
const captureCleanupGracePeriod = 2 * time.Minute

type captureCleanupSummary struct {
	FilesDeleted int   `json:"filesDeleted"`
	BytesFreed   int64 `json:"bytesFreed"`
	RecentKept   int   `json:"recentKept"`
}

func isCaptureOutputName(name string) bool {
	if !strings.HasPrefix(name, "capture-") {
		return false
	}
	stem := strings.TrimPrefix(name, "capture-")
	switch {
	case strings.HasSuffix(stem, ".pdf"):
		stem = strings.TrimSuffix(stem, ".pdf")
	case strings.HasSuffix(stem, ".png"):
		stem = strings.TrimSuffix(stem, ".png")
	default:
		return false
	}
	if len(stem) != 24 {
		return false
	}
	for i := 0; i < len(stem); i++ {
		if (stem[i] < '0' || stem[i] > '9') && (stem[i] < 'a' || stem[i] > 'f') {
			return false
		}
	}
	return true
}

func clearAgentCaptureArtifacts(configPath string, now time.Time) (captureCleanupSummary, error) {
	var result captureCleanupSummary
	if configPath == "" {
		return result, fmt.Errorf("Agent configuration path is required")
	}
	absolute, err := filepath.Abs(configPath)
	if err != nil {
		return result, err
	}
	info, err := os.Lstat(absolute)
	if err != nil {
		return result, fmt.Errorf("protected Agent config is unavailable: %w", err)
	}
	if !info.Mode().IsRegular() {
		return result, fmt.Errorf("protected Agent config must be a regular file")
	}
	if err := config.EnsureSecureFileACL(absolute); err != nil {
		return result, fmt.Errorf("Agent config security check failed: %w", err)
	}
	parent := filepath.Dir(absolute)
	if err := config.EnsureSecureDirectoryACL(parent); err != nil {
		return result, fmt.Errorf("Agent directory security check failed: %w", err)
	}
	dir := filepath.Join(parent, "e2e-captures")
	dirInfo, err := os.Lstat(dir)
	if os.IsNotExist(err) {
		return result, nil
	}
	if err != nil {
		return result, err
	}
	if !dirInfo.IsDir() || dirInfo.Mode()&os.ModeSymlink != 0 {
		return result, fmt.Errorf("Agent capture folder is not a real directory")
	}
	resolvedParent, err := filepath.EvalSymlinks(parent)
	if err != nil {
		return result, err
	}
	resolvedDir, err := filepath.EvalSymlinks(dir)
	if err != nil {
		return result, err
	}
	if filepath.Clean(resolvedDir) != filepath.Join(filepath.Clean(resolvedParent), "e2e-captures") {
		return result, fmt.Errorf("Agent capture folder redirects outside its protected parent")
	}
	if err := config.EnsureSecureDirectoryACL(dir); err != nil {
		return result, fmt.Errorf("Agent capture security check failed: %w", err)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return result, err
	}
	cutoff := now.Add(-captureCleanupGracePeriod)
	for _, entry := range entries {
		if !isCaptureOutputName(entry.Name()) || entry.Type()&os.ModeSymlink != 0 {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			return result, err
		}
		if !info.Mode().IsRegular() {
			continue
		}
		if info.ModTime().After(cutoff) {
			result.RecentKept++
			continue
		}
		if err := os.Remove(filepath.Join(dir, entry.Name())); err != nil {
			return result, fmt.Errorf("delete protected Agent test artifact: %w", err)
		}
		result.FilesDeleted++
		result.BytesFreed += info.Size()
	}
	return result, nil
}

func handleCaptureCleanup(args []string, defaultConfig string) error {
	fs := flag.NewFlagSet("capture-cleanup", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	configPath := fs.String("config", defaultConfig, "protected Agent service config")
	if err := fs.Parse(args); err != nil {
		return fmt.Errorf("invalid capture-cleanup arguments: %w", err)
	}
	if fs.NArg() != 0 {
		return fmt.Errorf("unexpected capture-cleanup arguments")
	}
	result, err := clearAgentCaptureArtifacts(*configPath, time.Now())
	if err != nil {
		return err
	}
	return json.NewEncoder(os.Stdout).Encode(result)
}
